79	function usageError(message: string): number {
80	  console.error(`${name}: ${message}`);
81	  console.error(`用法见 'node app.ts --help'`);
82	  return 2;
83	}
84	
85	interface ParsedOptions {
86	  devices: string[];
87	  from?: number;
88	  to?: number;
89	}
90	
91	/** 解析 --device/--from/--to 选项;出错返回错误消息字符串。 */
92	function parseOptions(rest: string[]): ParsedOptions | string {
93	  const devices: string[] = [];
94	  let from: number | undefined;
95	  let to: number | undefined;
96	  for (let i = 0; i < rest.length; i++) {
97	    let opt = rest[i];
98	    let value: string | undefined;
99	    const eq = opt.indexOf('=');
100	    if (opt.startsWith('--') && eq !== -1) {
101	      value = opt.slice(eq + 1);
102	      opt = opt.slice(0, eq);
103	    } else if (opt.startsWith('--')) {
104	      value = rest[i + 1];
105	      if (value === undefined) return `选项 '${opt}' 缺少值`;
106	      i++;
107	    } else {
108	      return `无法识别的参数 '${opt}'`;
109	    }
110	    if (opt === '--device') {
111	      if (value.trim() === '') return "'--device' 的值不能为空";
112	      devices.push(value);
113	    } else if (opt === '--from' || opt === '--to') {
114	      const ts = parseIso8601(value.trim());
115	      if (ts === null) {
116	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
117	      }
118	      if (opt === '--from') from = ts;
119	      else to = ts;
120	    } else {
121	      return `无法识别的选项 '${opt}'`;
122	    }
123	  }
124	  return { devices, from, to };
125	}
126	
127	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
128	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
129	  const out = new Map<string, string[]>();
130	  for (let i = 0; i < rest.length; i++) {
131	    let opt = rest[i];
132	    let value: string | undefined;
133	    const eq = opt.indexOf('=');
134	    if (opt.startsWith('--') && eq !== -1) {
135	      value = opt.slice(eq + 1);
136	      opt = opt.slice(0, eq);
137	    } else if (opt.startsWith('--')) {
138	      value = rest[i + 1];
139	      if (value === undefined) return `选项 '${opt}' 缺少值`;
140	      i++;
141	    } else {
142	      return `无法识别的参数 '${opt}'`;
143	    }
144	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
145	    const list = out.get(opt);
146	    if (list) list.push(value);
147	    else out.set(opt, [value]);
148	  }
149	  return out;
150	}
151	
152	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
153	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
154	  const list = flags.get(name);
155	  if (!list || list.length !== 1) return null;
156	  return list[0];
157	}
158	
159	/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
160	function dateFlag(value: string, label: string): number | string {
161	  const ts = parseUtcDate(value.trim());
162	  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
163	  return ts;
164	}
165	
166	function cmdRule(rest: string[]): number {
167	  const [sub, ...subrest] = rest;
168	  if (sub === 'list') {
169	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
170	    return cmdRuleList();
171	  }
172	  if (sub === 'create') {
173	    const flags = parseFlags(subrest, ['--id', '--device', '--threshold']);
174	    if (typeof flags === 'string') return usageError(flags);
175	    const idRaw = oneFlag(flags, '--id');
176	    const deviceRaw = oneFlag(flags, '--device');
177	    const thresholdRaw = oneFlag(flags, '--threshold');
178	    if (idRaw === null || deviceRaw === null || thresholdRaw === null) {
179	      return usageError("'rule create' 需要 --id、--device、--threshold 各恰好一个");
180	    }
181	    const id = idRaw.trim();
182	    if (id === '') return usageError('规则标识不能为空');
183	    const device = deviceRaw.trim();
184	    if (device === '') return usageError("'--device' 的值不能为空");
185	    const thresholdMilli = parseKwh(thresholdRaw.trim());
186	    if (thresholdMilli === null) {
187	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
188	    }
189	    return cmdRuleCreate({ id, device, thresholdMilli });
190	  }
191	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
192	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
193	}
194	
195	function cmdEvaluateEntry(rest: string[]): number {
196	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
197	  if (typeof flags === 'string') return usageError(flags);
198	  const ruleRaw = oneFlag(flags, '--rule');
199	  const fromRaw = oneFlag(flags, '--from');
200	  const toRaw = oneFlag(flags, '--to');
201	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
202	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
203	  }
204	  const ruleId = ruleRaw.trim();
205	  if (ruleId === '') return usageError('规则标识不能为空');
206	  const from = dateFlag(fromRaw, '起始日期');
207	  if (typeof from === 'string') return usageError(from);
208	  const to = dateFlag(toRaw, '结束日期');
209	  if (typeof to === 'string') return usageError(to);
210	  if (from >= to) return usageError('评估起日必须早于止日(--from < --to)');
211	  return cmdEvaluate({ ruleId, from, to });
212	}
213	
214	function cmdAlertsEntry(rest: string[]): number {
215	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
216	  if (typeof flags === 'string') return usageError(flags);
217	  const ruleRaw = oneFlag(flags, '--rule');
218	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
219	  const ruleId = ruleRaw.trim();
220	  if (ruleId === '') return usageError('规则标识不能为空');
221	  const fromList = flags.get('--from');
222	  const toList = flags.get('--to');
223	  if ((fromList !== undefined) !== (toList !== undefined)) {
224	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
225	  }
226	  let from: number | undefined;
227	  let to: number | undefined;
228	  if (fromList !== undefined) {
229	    const fromRaw = oneFlag(flags, '--from');
230	    const toRaw = oneFlag(flags, '--to');
231	    if (fromRaw === null || toRaw === null) {
232	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
233	    }
234	    const fromParsed = dateFlag(fromRaw, '起始日期');
235	    if (typeof fromParsed === 'string') return usageError(fromParsed);
236	    const toParsed = dateFlag(toRaw, '结束日期');
237	    if (typeof toParsed === 'string') return usageError(toParsed);
238	    if (fromParsed >= toParsed) return usageError('查询起日必须早于止日(--from < --to)');
239	    from = fromParsed;
240	    to = toParsed;
241	  }
242	  return cmdAlerts({ ruleId, from, to });
243	}
244	
245	function main(args: string[]): number {
246	  if (args.length === 0) {
247	    console.log(help);
248	    return 0;
249	  }
250	  const [cmd, ...rest] = args;
251	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
252	    console.log(help);
253	    return 0;
254	  }
255	
256	  if (cmd === 'import') {
257	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
258	    return cmdImport(rest[0]);
259	  }
260	
261	  if (cmd === 'readings') {
262	    const parsed = parseOptions(rest);
263	    if (typeof parsed === 'string') return usageError(parsed);
264	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
265	      return usageError('查询起点必须早于终点(--from < --to)');
266	    }
267	    return cmdReadings(parsed);
268	  }
269	
270	  if (cmd === 'daily') {
271	    const parsed = parseOptions(rest);
272	    if (typeof parsed === 'string') return usageError(parsed);
273	    if (parsed.from === undefined || parsed.to === undefined) {
274	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
275	    }
276	    if (parsed.from >= parsed.to) {
277	      return usageError('查询起点必须早于终点(--from < --to)');
278	    }
279	    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to });
280	  }
281	
282	  if (cmd === 'rule') return cmdRule(rest);
283	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
284	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
285	
286	  if (cmd === 'ack') {
287	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
288	    const alertId = rest[0].trim();
289	    if (alertId === '') return usageError('告警标识不能为空');
290	    return cmdAck(alertId);
291	  }
292	
293	  return usageError(`无法识别的参数 '${cmd}'`);
294	}
295	
296	process.exitCode = main(process.argv.slice(2));
297

