1	// import 与 readings 两个子命令的实现。
2	
3	import { readFileSync } from 'node:fs';
4	import { CsvError, parseCsv } from './csv.ts';
5	import { loadStore, saveStore, StoreError, dataFilePath, type Reading } from './store.ts';
6	import { formatIsoUtc, parseIso8601 } from './time.ts';
7	import { formatKwh, parseKwh } from './value.ts';
8	
9	export const CSV_HEADER = 'device,time,reading';
10	
11	function err(message: string): void {
12	  console.error(`meterwatch: ${message}`);
13	}
14	
15	/**
16	 * 导入 CSV 文件。整批成功或整批拒绝:
17	 * 任一行格式错误或读数冲突都不写入任何新数据。
18	 * 返回进程退出码。
19	 */
20	export function cmdImport(file: string): number {
21	  const storePath = dataFilePath();
22	
23	  let existing: Reading[];
24	  try {
25	    existing = loadStore(storePath);
26	  } catch (e) {
27	    if (e instanceof StoreError) {
28	      err(e.message);
29	      return 1;
30	    }
31	    throw e;
32	  }
33	
34	  let text: string;
35	  try {
36	    text = readFileSync(file, 'utf8');
37	  } catch (e) {
38	    err(`cannot read '${file}': ${(e as Error).message}`);
39	    return 1;
40	  }
41	
42	  let records;
43	  try {
44	    records = parseCsv(text);
45	  } catch (e) {
46	    if (e instanceof CsvError) {
47	      err(`${file}: ${e.message}`);
48	      return 1;
49	    }
50	    throw e;
51	  }
52	
53	  if (records.length === 0) {
54	    err(`${file}: empty file, expected header '${CSV_HEADER}'`);
55	    return 1;
56	  }
57	  const header = records[0];
58	  if (header.fields.length !== 3 || header.fields.join(',') !== CSV_HEADER) {
59	    err(`${file}: line ${header.line}: expected header '${CSV_HEADER}'`);
60	    return 1;
61	  }
62	
63	  // 逐行解析,收集全部格式错误。
64	  const errors: string[] = [];
65	  const rows: Array<Reading & { line: number }> = [];
66	  for (const rec of records.slice(1)) {
67	    if (rec.fields.length !== 3) {
68	      errors.push(`line ${rec.line}: expected 3 fields (device,time,reading), got ${rec.fields.length}`);
69	      continue;
70	    }
71	    const device = rec.fields[0].trim();
72	    if (device === '') {
73	      errors.push(`line ${rec.line}: device identifier is empty`);
74	      continue;
75	    }
76	    const ts = parseIso8601(rec.fields[1].trim());
77	    if (ts === null) {
78	      errors.push(`line ${rec.line}: invalid timestamp '${rec.fields[1].trim()}' (need ISO8601 with seconds and Z or numeric offset, e.g. 2026-01-01T00:00:00Z)`);
79	      continue;
80	    }
81	    const milli = parseKwh(rec.fields[2].trim());
82	    if (milli === null) {
83	      errors.push(`line ${rec.line}: invalid reading '${rec.fields[2].trim()}' (need a non-negative kWh value with at most 3 decimals)`);
84	      continue;
85	    }
86	    rows.push({ device, ts, milli, line: rec.line });
87	  }
88	  if (errors.length > 0) {
89	    for (const e of errors) err(`${file}: ${e}`);
90	    err(`import rejected: ${errors.length} invalid row(s); nothing was imported`);
91	    return 1;
92	  }
93	
94	  // 去重与冲突检测:先文件内部,再与已存数据比对。身份 = (设备, 实际时刻)。
95	  const key = (device: string, ts: number): string => `${device} ${ts}`;
96	  const inStore = new Map<string, number>();
97	  for (const r of existing) inStore.set(key(r.device, r.ts), r.milli);
98	
99	  const inFile = new Map<string, number>();
100	  const toAdd: Reading[] = [];
101	  const conflicts: string[] = [];
102	  let duplicates = 0;
103	  for (const r of rows) {
104	    const k = key(r.device, r.ts);
105	    const at = formatIsoUtc(r.ts);
