1	// 每日能耗阈值告警:规则管理、评估、告警历史查询与确认。
2	//
3	// - 规则由使用者指定非空唯一标识,绑定一个已有设备与非负、最多三位小数的
4	//   kWh 阈值;创建后设备与阈值固定。相同标识等价参数重试成功且不重复创建,
5	//   异参重试报冲突。
6	// - 评估针对连续完整 UTC 日期(起日含、止日不含),复用 daily 的完整时序、
7	//   均匀分摊与累计比例向下取整口径;仅全天有效覆盖的日期可判定,消耗严格
8	//   大于阈值才超限,等于阈值视为正常;有未知或下降覆盖时不可判定,不触发
9	//   也不恢复;零增长是有效数据。
10	// - 每条规则的每个日期独立跟踪:首次判定超限创建带唯一标识的未确认告警,
11	//   重复超限保留原标识且不新增事件;后续完整评估正常才记录恢复;恢复后再
12	//   超限创建新的未确认告警,旧记录保留,原确认不转移给新告警。
13	// - 确认按告警标识,已恢复告警也可确认;重复确认成功且不重复记事;确认不
14	//   改变超限或恢复状态。
15	// - 规则与历史存于数据目录的 alerts.json(与 readings.json 相互独立,导入
16	//   不触碰本文件,也不会自动评估)。创建、评估、确认都先在内存完成全部计算
17	//   再一次性原子写入,任何失败不留下部分状态;损坏或不可读存储明确报错,
18	//   绝不当作空库。
19	
20	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
21	import { dirname } from 'node:path';
22	import { alertFilePath, dataFilePath, loadStore, StoreError, type Reading } from './store.ts';
23	import { computeDay, DAY_SECONDS } from './report.ts';
24	import { formatIsoUtc, parseIso8601 } from './time.ts';
25	import { formatKwh, formatKwhBig } from './value.ts';
26	
27	export interface AlertRule {
28	  /** 规则标识(非空、唯一,已去首尾空白)。 */
29	  id: string;
30	  /** 绑定设备(已去首尾空白,区分大小写),创建后固定。 */
31	  device: string;
32	  /** 阈值,毫千瓦时整数,创建后固定。 */
33	  thresholdMilli: number;
34	}
35	
36	export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';
37	
38	export interface AlertEvent {
39	  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
40	  seq: number;
41	  type: AlertEventType;
42	  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
43	  consumptionMilli?: string;
44	}
45	
46	export interface AlertRecord {
47	  /** 告警标识,全局唯一。 */
48	  id: string;
49	  ruleId: string;
50	  /** UTC 日期,YYYY-MM-DD。 */
51	  date: string;
52	  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
53	  status: 'triggered' | 'recovered';
54	  acknowledged: boolean;
55	  events: AlertEvent[];
56	}
57	
58	interface AlertState {
59	  nextAlertNum: number;
60	  nextEventSeq: number;
61	  rules: AlertRule[];
62	  alerts: AlertRecord[];
63	}
64	
65	function err(message: string): void {
66	  console.error(`meterwatch: ${message}`);
67	}
68	
69	function emptyState(): AlertState {
70	  return { nextAlertNum: 1, nextEventSeq: 1, rules: [], alerts: [] };
71	}
72	
73	/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
74	function loadAlertState(path: string): AlertState {
75	  let text: string;
76	  try {
77	    text = readFileSync(path, 'utf8');
78	  } catch (e) {
79	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
80	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
81	  }
82	  let data: unknown;
83	  try {
84	    data = JSON.parse(text);
85	  } catch {
86	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
87	  }
88	  const bad = (what: string): StoreError =>
89	    new StoreError(`storage file ${path} is corrupted (${what})`);
90	  const o = data as Record<string, unknown>;
91	  if (o === null || typeof o !== 'object') throw bad('not an object');
92	  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
93	    throw bad('invalid nextAlertNum');
94	  }
95	  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
96	    throw bad('invalid nextEventSeq');
97	  }
98	  if (!Array.isArray(o.rules)) throw bad('missing rules array');
99	  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');
100	
101	  const ruleIds = new Set<string>();
102	  for (const r of o.rules as Array<Record<string, unknown>>) {
103	    const ok =
104	      r !== null &&
105	      typeof r === 'object' &&
106	      typeof r.id === 'string' &&
107	      r.id.length > 0 &&
108	      typeof r.device === 'string' &&
109	      r.device.length > 0 &&
110	      Number.isSafeInteger(r.thresholdMilli) &&
111	      (r.thresholdMilli as number) >= 0;
112	    if (!ok) throw bad('invalid rule entry');
113	    if (ruleIds.has(r.id as string)) throw bad(`duplicate rule id '${r.id}'`);
114	    ruleIds.add(r.id as string);
115	  }
116	
117	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
118	  const alertIds = new Set<string>();
119	  for (const a of o.alerts as Array<Record<string, unknown>>) {
120	    const ok =
121	      a !== null &&
122	      typeof a === 'object' &&
123	      typeof a.id === 'string' &&
124	      a.id.length > 0 &&
125	      typeof a.ruleId === 'string' &&
126	      ruleIds.has(a.ruleId) &&
127	      typeof a.date === 'string' &&
128	      DATE_RE.test(a.date) &&
129	      (a.status === 'triggered' || a.status === 'recovered') &&
130	      typeof a.acknowledged === 'boolean' &&
131	      Array.isArray(a.events);
132	    if (!ok) throw bad('invalid alert entry');
133	    if (alertIds.has(a.id as string)) throw bad(`duplicate alert id '${a.id}'`);
134	    alertIds.add(a.id as string);
135	    for (const e of a.events as Array<Record<string, unknown>>) {
136	      const eok =
137	        e !== null &&
138	        typeof e === 'object' &&
139	        Number.isSafeInteger(e.seq) &&
140	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
141	        (e.consumptionMilli === undefined ||
142	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
143	      if (!eok) throw bad('invalid alert event');
144	    }
145	  }
146	  return data as unknown as AlertState;
147	}
148	
149	/** 原子写入告警存储;失败抛错,原有数据保持不变。 */
150	function saveAlertState(path: string, state: AlertState): void {
151	  mkdirSync(dirname(path), { recursive: true });
152	  const tmp = `${path}.tmp-${process.pid}`;
153	  const body = JSON.stringify({ version: 1, ...state }, null, 2) + '\n';
154	  try {
155	    writeFileSync(tmp, body, 'utf8');
156	    renameSync(tmp, path);
157	  } catch (e) {
158	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
159	  }
160	}
161	
162	/**
163	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
164	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
165	 */
166	function deviceSeries(device: string): Reading[] {
167	  const all = loadStore(dataFilePath());
168	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
169	  for (let i = 1; i < series.length; i++) {
170	    if (series[i].ts === series[i - 1].ts) {
171	      throw new StoreError(
172	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
173	      );
174	    }
175	  }
176	  return series;
177	}
178	
179	/** 不可判定原因(未知/异常覆盖秒数)。 */
180	function undecidableReason(stats: { unknown: number; anomaly: number }): string {
181	  return `undecidable (unknown=${stats.unknown}s anomaly=${stats.anomaly}s)`;
182	}
183	
184	/**
185	 * 创建规则。相同标识等价参数(同设备、同阈值)重试成功且不重复创建;
186	 * 异参重试报冲突。设备必须已有存储读数。返回进程退出码。
187	 */
188	export function cmdRuleCreate(opts: {
189	  id: string;
190	  device: string;
191	  thresholdMilli: number;
192	}): number {
193	  const statePath = alertFilePath();
194	  let state: AlertState;
195	  try {
196	    state = loadAlertState(statePath);
197	  } catch (e) {
198	    if (e instanceof StoreError) {
199	      err(e.message);
200	      return 1;
201	    }
202	    throw e;
203	  }
204	
205	  const existing = state.rules.find((r) => r.id === opts.id);
206	  if (existing) {
207	    if (existing.device === opts.device && existing.thresholdMilli === opts.thresholdMilli) {
208	      console.log(
209	        `rule '${opts.id}' already exists with identical parameters (device=${existing.device} threshold=${formatKwh(existing.thresholdMilli)} kWh); unchanged`,
210	      );
211	      return 0;
212	    }
213	    err(
214	      `rule '${opts.id}' already exists with different parameters ` +
215	        `(stored device=${existing.device} threshold=${formatKwh(existing.thresholdMilli)} kWh, ` +
216	        `got device=${opts.device} threshold=${formatKwh(opts.thresholdMilli)} kWh); conflict`,
217	    );
218	    return 1;
219	  }
220	
221	  let devices: Set<string>;
222	  try {
223	    devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
224	  } catch (e) {
225	    if (e instanceof StoreError) {
226	      err(e.message);
227	      return 1;
228	    }
229	    throw e;
230	  }
231	  if (!devices.has(opts.device)) {
232	    err(`unknown device '${opts.device}': no stored readings; import readings before creating a rule`);
233	    return 1;
234	  }
235	
236	  state.rules.push({ id: opts.id, device: opts.device, thresholdMilli: opts.thresholdMilli });
237	  try {
238	    saveAlertState(statePath, state);
239	  } catch (e) {
240	    if (e instanceof StoreError) {
241	      err(e.message);
242	      return 1;
243	    }
244	    throw e;
245	  }
246	  console.log(
247	    `rule '${opts.id}' created: device=${opts.device} threshold=${formatKwh(opts.thresholdMilli)} kWh`,
248	  );
249	  return 0;
250	}
251	
252	/** 列出全部规则。只读。返回进程退出码。 */
253	export function cmdRuleList(): number {
254	  let state: AlertState;
255	  try {
256	    state = loadAlertState(alertFilePath());
257	  } catch (e) {
258	    if (e instanceof StoreError) {
259	      err(e.message);
260	      return 1;
261	    }
262	    throw e;
263	  }
264	  if (state.rules.length === 0) {
265	    console.log('no rules defined');
266	    return 0;
267	  }
268	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
269	  for (const r of rules) {
270	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
271	    console.log(
272	      `rule ${r.id}  device=${r.device}  threshold=${formatKwh(r.thresholdMilli)} kWh  open alerts=${open}`,
273	    );
274	  }
275	  return 0;
276	}
277	
278	/**
279	 * 评估规则在连续完整 UTC 日期范围 [from, to) 上的超限情况。
280	 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交。
281	 * 返回进程退出码。
282	 */
283	export function cmdEvaluate(opts: { ruleId: string; from: number; to: number }): number {
284	  const statePath = alertFilePath();
285	  let state: AlertState;
286	  let rule: AlertRule;
287	  let series: Reading[];
288	  try {
289	    state = loadAlertState(statePath);
290	    const found = state.rules.find((r) => r.id === opts.ruleId);
291	    if (!found) {
292	      err(`unknown rule '${opts.ruleId}'`);
293	      return 1;
294	    }
295	    rule = found;
296	    series = deviceSeries(rule.device);
297	  } catch (e) {
298	    if (e instanceof StoreError) {
299	      err(e.message);
300	      return 1;
301	    }
302	    throw e;
303	  }
304	
305	  const threshold = BigInt(rule.thresholdMilli);
306	  const lines: string[] = [];
307	  for (let dayStart = opts.from; dayStart < opts.to; dayStart += DAY_SECONDS) {
308	    const date = formatIsoUtc(dayStart).slice(0, 10);
309	    const stats = computeDay(series, dayStart, dayStart + DAY_SECONDS);
310	    if (stats.unknown > 0 || stats.anomaly > 0) {
311	      // 有未知或下降覆盖:不可判定,不触发也不恢复。
312	      lines.push(`  ${date}  ${undecidableReason(stats)}  no alert action`);
313	      continue;
314	    }
315	    const exceeded = stats.consumption > threshold;
316	    const cmp =
317	      `consumption=${formatKwhBig(stats.consumption)} kWh ` +
318	      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
319	    const open = state.alerts.find(
320	      (a) => a.ruleId === rule.id && a.date === date && a.status === 'triggered',
321	    );
322	    if (exceeded) {
323	      if (open) {
324	        // 重复超限:保留原标识,不新增事件。
325	        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered`);
326	      } else {
327	        const id = `alert-${state.nextAlertNum++}`;
328	        state.alerts.push({
329	          id,
330	          ruleId: rule.id,
331	          date,
332	          status: 'triggered',
333	          acknowledged: false,
334	          events: [
335	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
336	          ],
337	        });
338	        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)`);
339	      }
340	    } else {
341	      if (open) {
342	        open.status = 'recovered';
343	        open.events.push({
344	          seq: state.nextEventSeq++,
345	          type: 'recovered',
346	          consumptionMilli: stats.consumption.toString(),
347	        });
348	        lines.push(`  ${date}  ${cmp}  NORMAL  alert ${open.id} recovered`);
349	      } else {
350	        lines.push(`  ${date}  ${cmp}  NORMAL  no alert`);
351	      }
352	    }
353	  }
354	
355	  try {
356	    saveAlertState(statePath, state);
357	  } catch (e) {
358	    if (e instanceof StoreError) {
359	      err(e.message);
360	      return 1;
361	    }
362	    throw e;
363	  }
364	
365	  console.log(
366	    `rule: ${rule.id}  device=${rule.device}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
367	  );
368	  for (const line of lines) console.log(line);
369	  return 0;
370	}
371	
372	/**
373	 * 查询规则的告警历史。只读,不修改数据。
374	 * 给定日期范围时逐日展示消耗或不可判定原因及各次告警;省略范围时展示
375	 * 有告警记录的全部日期。返回进程退出码。
376	 */
377	export function cmdAlerts(opts: { ruleId: string; from?: number; to?: number }): number {
378	  let state: AlertState;
379	  let rule: AlertRule;
380	  let series: Reading[];
381	  try {
382	    state = loadAlertState(alertFilePath());
383	    const found = state.rules.find((r) => r.id === opts.ruleId);
384	    if (!found) {
385	      err(`unknown rule '${opts.ruleId}'`);
386	      return 1;
387	    }
388	    rule = found;
389	    series = deviceSeries(rule.device);
390	  } catch (e) {
391	    if (e instanceof StoreError) {
392	      err(e.message);
393	      return 1;
394	    }
395	    throw e;
396	  }
397	
398	  let dayStarts: number[];
399	  if (opts.from !== undefined && opts.to !== undefined) {
400	    dayStarts = [];
401	    for (let d = opts.from; d < opts.to; d += DAY_SECONDS) dayStarts.push(d);
402	  } else {
403	    const dates = [
404	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
405	    ].sort();
406	    dayStarts = dates.map((d) => parseIso8601(`${d}T00:00:00Z`) as number);
407	  }
408	
409	  console.log(
410	    `rule: ${rule.id}  device=${rule.device}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
411	  );
412	  if (dayStarts.length === 0) {
413	    console.log(`  no alerts recorded for rule '${rule.id}'`);
414	    return 0;
415	  }
416	
417	  const threshold = BigInt(rule.thresholdMilli);
418	  for (const dayStart of dayStarts) {
419	    const date = formatIsoUtc(dayStart).slice(0, 10);
420	    const stats = computeDay(series, dayStart, dayStart + DAY_SECONDS);
421	    if (stats.unknown > 0 || stats.anomaly > 0) {
422	      console.log(`  ${date}  ${undecidableReason(stats)}`);
423	    } else {
424	      const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
425	      console.log(
426	        `  ${date}  consumption=${formatKwhBig(stats.consumption)} kWh ` +
427	          `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)`,
428	      );
429	    }
430	    const alerts = state.alerts
431	      .filter((a) => a.ruleId === rule.id && a.date === date)
432	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
433	    if (alerts.length === 0) {
434	      console.log('    no alerts');
435	      continue;
436	    }
437	    for (const a of alerts) {
438	      console.log(
439	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
440	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
441	      );
442	      const events = a.events
443	        .map((e) => {
444	          const consumption =
445	            e.consumptionMilli !== undefined
446	              ? ` (consumption=${formatKwhBig(BigInt(e.consumptionMilli))} kWh)`
447	              : '';
448	          return `#${e.seq} ${e.type}${consumption}`;
449	        })
450	        .join(', ');
451	      console.log(`      events: ${events}`);
452	    }
