1	// 轻量 CSV 解析:支持标准双引号字段、"" 转义双引号、字段内换行,
2	// 以及 LF / CRLF / CR 换行。空行(完全无字符的行)被跳过。
3	
4	export interface CsvRecord {
5	  fields: string[];
6	  /** 记录起始行号(1 起)。 */
7	  line: number;
8	}
9	
10	export class CsvError extends Error {}
11	
12	/**
13	 * 解析 CSV 文本为记录数组。
14	 * 语法错误(引号未闭合、引号后出现非法字符等)抛出 CsvError,消息含行号。
15	 */
16	export function parseCsv(text: string): CsvRecord[] {
17	  if (text.startsWith('﻿')) text = text.slice(1); // 去掉 UTF-8 BOM
18	
19	  const records: CsvRecord[] = [];
20	  let fields: string[] = [];
21	  let field = '';
22	  let inQuotes = false;
23	  let afterQuote = false; // 刚结束一个引号字段,只接受逗号/换行/EOF
24	  let started = false; // 当前记录是否已有任何字符
25	  let line = 1;
26	  let recordLine = 1;
27	
28	  const endField = (): void => {
29	    fields.push(field);
30	    field = '';
31	    afterQuote = false;
32	  };
33	  const endRecord = (): void => {
34	    endField();
35	    records.push({ fields, line: recordLine });
36	    fields = [];
37	    started = false;
38	  };
39	
40	  for (let i = 0; i < text.length; i++) {
41	    const ch = text[i];
42	    if (inQuotes) {
43	      if (ch === '"') {
44	        if (text[i + 1] === '"') {
45	          field += '"';
46	          i++;
47	        } else {
48	          inQuotes = false;
49	          afterQuote = true;
50	        }
51	      } else {
52	        if (ch === '\n') line++;
53	        field += ch;
54	      }
55	      continue;
56	    }
57	    if (afterQuote) {
58	      if (ch === ',') {
59	        endField();
60	      } else if (ch === '\n' || ch === '\r') {
61	        if (ch === '\r' && text[i + 1] === '\n') i++;
62	        line++;
63	        endRecord();
64	        recordLine = line;
65	      } else {
66	        throw new CsvError(`line ${line}: unexpected character after closing quote`);
67	      }
68	      continue;
69	    }
70	    if (ch === '"') {
71	      if (field !== '') {
72	        throw new CsvError(`line ${line}: unexpected quote inside unquoted field`);
73	      }
74	      inQuotes = true;
75	      started = true;
76	    } else if (ch === ',') {
