31	import { formatIsoUtc, parseIso8601 } from './time.ts';
32	import { formatKwh } from './value.ts';
33	
34	export interface AlertRule {
35	  /** 规则标识(非空、唯一,已去首尾空白)。 */
36	  id: string;
37	  /** 绑定设备(已去首尾空白,区分大小写),创建后固定。 */
38	  device: string;
39	  /** 阈值,毫千瓦时 BigInt,创建后固定。 */
40	  thresholdMilli: bigint;
41	}
42	
43	export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';
44	
45	export interface AlertEvent {
46	  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
47	  seq: number;
48	  type: AlertEventType;
49	  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
50	  consumptionMilli?: string;
51	}
52	
53	export interface AlertRecord {
54	  /** 告警标识,全局唯一。 */
55	  id: string;
56	  ruleId: string;
57	  /** UTC 日期,YYYY-MM-DD。 */
58	  date: string;
59	  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
60	  status: 'triggered' | 'recovered';
61	  acknowledged: boolean;
62	  events: AlertEvent[];
63	}
64	
