80	/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
81	function loadAlertState(path: string): AlertState {
82	  let text: string;
83	  try {
84	    text = readFileSync(path, 'utf8');
85	  } catch (e) {
86	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
87	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
88	  }
89	  let data: unknown;
90	  try {
91	    data = JSON.parse(text);
92	  } catch {
93	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
94	  }
95	  const bad = (what: string): StoreError =>
96	    new StoreError(`storage file ${path} is corrupted (${what})`);
97	  const o = data as Record<string, unknown>;
98	  if (o === null || typeof o !== 'object') throw bad('not an object');
99	  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
100	    throw bad('invalid nextAlertNum');
101	  }
102	  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
103	    throw bad('invalid nextEventSeq');
104	  }
105	  if (!Array.isArray(o.rules)) throw bad('missing rules array');
106	  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');
107	
108	  const ruleIds = new Set<string>();
109	  const rules: AlertRule[] = [];
110	  for (const r of o.rules as Array<Record<string, unknown>>) {
111	    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
112	    // 按损坏数据拒绝,不猜测原值。
113	    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
114	    const ok =
115	      r !== null &&
116	      typeof r === 'object' &&
117	      typeof r.id === 'string' &&
118	      r.id.length > 0 &&
119	      typeof r.device === 'string' &&
120	      r.device.length > 0 &&
121	      thresholdMilli !== null;
122	    if (!ok) throw bad('invalid rule entry');
123	    if (ruleIds.has(r.id as string)) throw bad(`duplicate rule id '${r.id}'`);
124	    ruleIds.add(r.id as string);
125	    rules.push({ id: r.id as string, device: r.device as string, thresholdMilli: thresholdMilli as bigint });
126	  }
127	
128	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
129	  const alertIds = new Set<string>();
130	  for (const a of o.alerts as Array<Record<string, unknown>>) {
131	    const ok =
132	      a !== null &&
133	      typeof a === 'object' &&
134	      typeof a.id === 'string' &&
135	      a.id.length > 0 &&
136	      typeof a.ruleId === 'string' &&
137	      ruleIds.has(a.ruleId) &&
138	      typeof a.date === 'string' &&
139	      DATE_RE.test(a.date) &&
140	      (a.status === 'triggered' || a.status === 'recovered') &&
141	      typeof a.acknowledged === 'boolean' &&
142	      Array.isArray(a.events);
143	    if (!ok) throw bad('invalid alert entry');
144	    if (alertIds.has(a.id as string)) throw bad(`duplicate alert id '${a.id}'`);
145	    alertIds.add(a.id as string);
146	    for (const e of a.events as Array<Record<string, unknown>>) {
147	      const eok =
148	        e !== null &&
149	        typeof e === 'object' &&
150	        Number.isSafeInteger(e.seq) &&
151	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
152	        (e.consumptionMilli === undefined ||
153	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
154	      if (!eok) throw bad('invalid alert event');
